for slug, txt in N.items():
    caminho = os.path.join('exports', slug, 'roteiro.txt')
    io.open(caminho, 'w', encoding='utf-8').write(txt.strip() + '\n')
    os.remove(os.path.join('exports', slug, slug + '.mp4')) if os.path.exists(os.path.join('exports', slug, slug + '.mp4')) else None
